}

.mt-totals-item {
    /* Table-based layout instead of flexbox for better compatibility */
    display: table;
    width: 100%;
    padding: 10px 0; 
    font-size: 0.95em;
}
.mt-totals-label {
    display: table-cell;
    text-align: left;
    color: #444; 
}
.mt-totals-value {
    display: table-cell;
    text-align: right;
    font-weight: 600;
    color: #171717;
    font-family: "Menlo", "Monaco", "Consolas", "Courier New", monospace; 
}

.mt-totals-divider {
    border: 0;
