    padding-top: 12px; 
}

.mt-totals-item.mt-grand-total .mt-totals-label,
.mt-totals-item.mt-grand-total .mt-totals-value {
    font-weight: 700; 
    font-size: 1.15em; 
    color: #171717;
}

.mt-totals-item.mt-grand-total .mt-totals-value {
    color: #B58B0F;
}

.mt-table-container { 
    overflow-x: auto;
    background-color: #fafafa;
    -webkit-border-radius: 8px;
       -moz-border-radius: 8px;
            border-radius: 8px;
}

.mt-table-container table { 
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed; 
}

.mt-table-container caption { 
    caption-side: top;
    font-size: 1.4em;
    font-weight: bold;
    padding: 15px;
    color: #171717;
    text-align: left;
}

/* Table Header */
.mt-table-container thead th { 
    background-color: #171717; 
    color: #f0f0f0;
    padding: 15px 20px;
    text-align: left;
    font-weight: 600;
    letter-spacing: 0.5px;
    border-bottom: 2px solid #333;
}

.mt-table-container thead th.mt-col-number { width: 10%; }
.mt-table-container thead th.mt-col-description { width: 65%; }
.mt-table-container thead th.mt-col-amount {
    width: 40%;
    text-align: right; 
}

.mt-table-container tbody td { 
    padding: 12px 20px;
    border-bottom: 1px solid #e0e0e0;
    color: #555;
    word-break: break-word; 
    font-size: 0.9em;
}

.mt-table-container tbody td.mt-col-amount-data {
    text-align: right;
    font-family: "Menlo", "Monaco", "Consolas", "Courier New", monospace; 
}

.mt-table-container tbody tr:nth-child(even) {
    background-color: #f4f4f5;
}

.mt-table-container tbody tr:hover {
    background-color: #e9e9e9;
    cursor: default;
}

.mt-table-container tbody tr:last-child td {
    border-bottom: none;
}

.page-number { display: none!important; }

